gPo(){return"\u091f\u094d\u0930\u093e\u092f\u0932 \u0938\u094d\u0925\u093f\u0924\u093f, \u0938\u0926\u0938\u094d\u092f\u0924\u093e, \u0914\u0930 \u092d\u0941\u0917\u0924\u093e\u0928"},
gPu(){return"\u0939\u093e\u0925 \u092e\u0947\u0902 \u0928\u0915\u0926"},
gPt(){return"\u0906\u092a\u0915\u093e \u0930\u0916\u093e \u0939\u0941\u0906 \u0928\u0915\u0926, \u0935\u094d\u092f\u092f, \u0914\u0930 \u0939\u0938\u094d\u0924\u093e\u0902\u0924\u0930\u0923"},
gPG(){return"\u0935\u093f\u0924\u094d\u0924\u0940\u092f \u0935\u0930\u094d\u0937"},
gPF(){return"\u0915\u093f\u0938\u0940 \u0935\u0930\u094d\u0937 \u0915\u0940 \u092c\u0939\u093f\u092f\u093e\u0902 \u092c\u0902\u0926 \u092f\u093e \u092b\u093f\u0930 \u0938\u0947 \u0916\u094b\u0932\u0947\u0902"},
gPE(){return"\u0935\u094d\u092f\u092f \u0936\u094d\u0930\u0947\u0923\u093f\u092f\u093e\u0902"},
gPD(){return"\u0938\u0902\u092a\u093e\u0926\u0928 \u092f\u094b\u0917\u094d\u092f, \u0938\u092e\u0942\u0939\u0940\u0915\u0930\u0923 \u092f\u094b\u0917\u094d\u092f \u2014 \u091c\u0948\u0938\u0947 \u0935\u093e\u0939\u0928 \u0935\u094d\u092f\u092f > \u0935\u093e\u0939\u0928 1 > \u092a\u0947\u091f\u094d\u0930\u094b\u0932"},
gPQ(){return"\u0938\u0947\u0932\u094d\u0938\u092e\u0948\u0928 \u092a\u0939\u091a\u093e\u0928 \u0938\u092e\u0940\u0915\u094d\u0937\u093e"},
gPP(){return"\u0917\u094d\u0930\u093e\u0939\u0915\u094b\u0902, \u091a\u093e\u0932\u093e\u0928\u094b\u0902, \u0914\u0930 \u0915\u092e\u0940\u0936\u0928 \u0926\u0930\u094b\u0902 \u092a\u0930 \u092a\u0941\u0930\u093e\u0928\u0947 \u0938\u0947\u0932\u094d\u0938\u092e\u0948\u0928 \u0928\u093e\u092e\u094b\u0902 \u0915\u094b \u090f\u0915 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0938\u094d\u091f\u093e\u092b \u0916\u093e\u0924\u0947 \u0938\u0947 \u0932\u093f\u0902\u0915 \u0915\u0930\u0947\u0902"},
gUf(){return"\u092f\u0939 \u0921\u093f\u0935\u093e\u0907\u0938 \u092b\u093c\u093f\u0902\u0917\u0930\u092a\u094d\u0930\u093f\u0902\u091f \u092f\u093e \u092b\u093c\u0947\u0938 \u0905\u0928\u0932\u0949\u0915 \u0915\u093e \u0938\u092e\u0930\u094d\u0925\u0928 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u093e\u0964"},
