gUe(){return"\u092b\u093c\u093f\u0902\u0917\u0930\u092a\u094d\u0930\u093f\u0902\u091f / \u092b\u093c\u0947\u0938 \u0905\u0928\u0932\u0949\u0915 \u091a\u093e\u0932\u0942 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0947\u0902"},
gVB(){return"\u0915\u0902\u092a\u0928\u0940 / \u0926\u0941\u0915\u093e\u0928 \u0915\u093e \u0928\u093e\u092e *"},
gVA(){return"\u0906\u0935\u0936\u094d\u092f\u0915 \u2014 \u0906\u092a\u0915\u0947 \u0926\u094d\u0935\u093e\u0930\u093e \u092c\u0928\u093e\u090f \u0917\u090f \u0939\u0930 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092a\u0930 \u091b\u092a\u0924\u093e \u0939\u0948"},
gVL(){return"\u091f\u0948\u0917\u0932\u093e\u0907\u0928 (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gVK(){return'\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c\u094b\u0902 \u092a\u0930 \u0906\u092a\u0915\u0947 \u0928\u093e\u092e \u0915\u0947 \u0928\u0940\u091a\u0947 \u091b\u092a\u0940 \u090f\u0915 \u091b\u094b\u091f\u0940 \u092a\u0902\u0915\u094d\u0924\u093f, \u091c\u0948\u0938\u0947 "FOR TRADING"'},
